ddl:
CREATE TABLE User (
    Email VARCHAR(255),
    Password VARCHAR(255),
    Phone VARCHAR(255),
    User_ID INTEGER PRIMARY KEY,
    User_Name VARCHAR(255)
);

CREATE TABLE Role (
    Role_Description VARCHAR(255),
    Role_ID INTEGER PRIMARY KEY,
    Role_Name VARCHAR(255)
);

CREATE TABLE Permission (
    Permission_Description VARCHAR(255),
    Permission_ID INTEGER PRIMARY KEY,
    Permission_Name VARCHAR(255)
);

CREATE TABLE Role_Permission_Assignment (
    Permission_Assignment_End_Time DATETIME,
    Permission_Assignment_Start_Time DATETIME,
    Permission_ID INTEGER,
    Role_ID INTEGER,
    PRIMARY KEY (Role_ID, Permission_ID, Permission_Assignment_Start_Time)
);

CREATE TABLE User_Role (
    Role_Assignment_End_Time DATETIME,
    Role_Assignment_Start_Time DATETIME,
    Role_ID INTEGER NOT NULL,
    User_ID INTEGER NOT NULL,
    PRIMARY KEY (User_ID, Role_ID, Role_Assignment_Start_Time),
    FOREIGN KEY (Role_ID) REFERENCES Role(Role_ID),
    FOREIGN KEY (User_ID) REFERENCES User(User_ID)
);
